import { useState, useEffect } from 'react';
import type { Book } from './types';

// null = loading in progress; array (possibly empty) = load complete
export function App(): JSX.Element {
  const [books, setBooks] = useState<Book[] | null>(null);

  useEffect(() => {
    // Replace with real data fetch via adapter
    setBooks([]);
  }, []);

  return (
    <main>
      {books === null ? <p>Loading…</p> : <p>{books.length} books</p>}
    </main>
  );
}
